import type { Option } from "effect";
import type { Command } from "foldkit";
import * as Ui from "@foldkit/ui";

export const { Model } = Ui.Tabs;
export type Model = Ui.Tabs.Model;

export const {
  CompletedFocusTab,
  FocusTab,
  FocusedTab,
  Message,
  OutMessage,
  Selected,
  SelectedTab,
  create,
  init,
} = Ui.Tabs;
export type ActivationMode = Ui.Tabs.ActivationMode;
export type FocusedTab = Ui.Tabs.FocusedTab;
export type InitConfig = Ui.Tabs.InitConfig;
export type Message = Ui.Tabs.Message;
export type Orientation = Ui.Tabs.Orientation;
export type OutMessage<Value extends string = string> =
  Ui.Tabs.OutMessage<Value>;
export type RenderInfo<Value extends string = string> =
  Ui.Tabs.RenderInfo<Value>;
export type Selected<Value extends string = string> = Ui.Tabs.Selected<Value>;
export type SelectedTab = Ui.Tabs.SelectedTab;
export type TabInfo<Value extends string = string> = Ui.Tabs.TabInfo<Value>;
export type ViewInputs<Value extends string = string> =
  Ui.Tabs.ViewInputs<Value>;
export type InitReturn = readonly [Model, readonly Command.Command<Message>[]];
export type UpdateReturn<Value extends string = string> = readonly [
  Model,
  readonly Command.Command<Message>[],
  Option.Option<OutMessage<Value>>,
];

export const initialize = (config: InitConfig): InitReturn => [
  init(config),
  [],
];

export {
  panelClasses,
  tabClasses,
  tabListClasses,
  tabsRootClasses,
  tabsView,
  verticalTabListClasses,
  verticalTabsRootClasses,
} from "./view";
export type { TabsViewInput } from "./view";

import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import type { RenderInfo } from "./index";

export const tabsRootClasses = "max-w-md space-y-3";

export const tabListClasses =
  "inline-flex rounded-lg border border-gray-200 bg-gray-100 p-1";

export const verticalTabsRootClasses =
  "grid max-w-lg gap-3 sm:grid-cols-[11rem_1fr]";

export const verticalTabListClasses =
  "flex flex-col rounded-lg border border-gray-200 bg-gray-100 p-1";

export const tabClasses =
  "rounded-md px-3 py-1.5 text-sm font-medium text-gray-600 transition hover:text-gray-950 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-600 data-[selected]:bg-white data-[selected]:text-gray-950 data-[selected]:shadow-sm disabled:cursor-not-allowed disabled:opacity-50";

export const panelClasses =
  "rounded-lg border border-gray-200 bg-white p-4 text-sm text-gray-700";

export type TabsViewInput<Value extends string = string> = Readonly<{
  render: RenderInfo<Value>;
  panelContent: Record<Value, string>;
  orientation?: "Horizontal" | "Vertical";
}>;

export const tabsView = <Value extends string>({
  render,
  panelContent,
  orientation = "Horizontal",
}: TabsViewInput<Value>): Html => {
  const h = html();
  const activeTab = render.tabs[render.activeIndex];
  const isVertical = orientation === "Vertical";

  return h.div(
    [h.Class(isVertical ? verticalTabsRootClasses : tabsRootClasses)],
    [
      h.div(
        [
          ...render.tablist,
          h.Class(isVertical ? verticalTabListClasses : tabListClasses),
        ],
        render.tabs.map((tab) =>
          h.button([...tab.tab, h.Class(tabClasses)], [tab.value])
        )
      ),
      activeTab === undefined
        ? h.empty
        : h.div(
            [...activeTab.panel, h.Class(panelClasses)],
            [panelContent[activeTab.value]]
          ),
    ]
  );
};

import { Match as M, Option, Schema as S } from "effect";
import { Command, Scene, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, test } from "vitest";

import * as Tabs from "./index";

type Tab = "One" | "Two";
const DemoTabs = Tabs.create<Tab>();
const tabValues: readonly Tab[] = ["One", "Two"];

const GotTabsMessage = m("GotTabsMessage", { message: Tabs.Message });
const Model = S.Struct({ tabs: Tabs.Model, status: S.String });
type Model = typeof Model.Type;
const Message = S.Union([GotTabsMessage]);
type Message = typeof Message.Type;

const initialModel: Model = {
  tabs: Tabs.initialize({ id: "registry-tabs" })[0],
  status: "Selected: One",
};

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotTabsMessage: ({ message }) => {
        const [tabs, commands, maybeOutMessage] = DemoTabs.update(
          model.tabs,
          message
        );
        const status = Option.match(maybeOutMessage, {
          onNone: () => model.status,
          onSome: M.type<Tabs.OutMessage<Tab>>().pipe(
            M.tagsExhaustive({
              Selected: ({ value }) => `Selected: ${value}`,
            })
          ),
        });

        return [
          evo(model, { tabs: () => tabs, status: () => status }),
          Command.mapMessages(commands, (message) =>
            GotTabsMessage({ message })
          ),
        ];
      },
    })
  );

const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [],
    [
      h.submodel({
        slotId: model.tabs.id,
        model: model.tabs,
        view: DemoTabs.view,
        viewInputs: {
          tabs: tabValues,
          ariaLabel: "Registry tabs",
          toView: (render) =>
            Tabs.tabsView({
              render,
              panelContent: {
                One: "Panel one",
                Two: "Panel two",
              },
            }),
        },
        toParentMessage: (message) => GotTabsMessage({ message }),
      }),
      h.p([], [model.status]),
    ]
  );
});

describe("Tabs registry view", () => {
  test("selects tabs and resolves focus command", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("tab", { name: "One" })).toHaveAttr(
        "aria-selected",
        "true"
      ),
      Scene.click(Scene.role("tab", { name: "Two" })),
      Scene.Command.resolve(
        Tabs.FocusTab({ id: "registry-tabs", index: 1 }),
        Tabs.CompletedFocusTab(),
        (message) => GotTabsMessage({ message })
      ),
      Scene.expect(Scene.text("Selected: Two")).toExist()
    );
  });
});
